/*
https://data.humdata.org/dataset/nepal-municipalities
*/

SET CLIENT_ENCODING TO UTF8;
SET STANDARD_CONFORMING_STRINGS TO ON;
BEGIN;
CREATE TABLE "geography"."admin3" (gid serial,
"admin0name" varchar(50),
"admin0pcod" varchar(50),
"admin1name" varchar(50),
"admin1pcod" varchar(50),
"admin2name" varchar(50),
"admin2pcod" varchar(50),
"admin3name" varchar(50),
"admin3pcod" varchar(50),
"admin3refn" varchar(50),
"admin3altn" varchar(50),
"admin3al_1" varchar(50),
"date" date,
"validon" date,
"validto" date,
"shape_star" numeric,
"shape_stle" numeric,
"shape_leng" numeric,
"shape_area" numeric,
"geom" geometry(MULTIPOLYGON, 4326, 2));
ALTER TABLE "geography"."admin3" ADD PRIMARY KEY (gid);
CREATE INDEX "admin3_geom_gist" ON "geography"."admin3" USING GIST ("geom");
COMMIT;
